__NUXT_JSONP__("/de/about", (function(a,b){return {data:[{details:{slug:"de",pageTitle:"Was ist MLI? | Mentor Language Institute",pageDescription:b,section1:{title:"Was ist MLI?",description:[b,"Wir helfen Studenten von der ganzen Welt ihr Englisch zu verbessern."]},section2:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fpay-less-for-quality-classes.jpg",title:"Weniger zahlen für qualitativ hochwertige Kurse",description:["Wir schätzen zwei Dinge: \u003Cb\u003E“Bildungsqualität”\u003C\u002Fb\u003E  und  \u003Cb\u003E“Preis.”\u003Cb\u003E","Englisch ist die Weltsprache und ein nützliches Werkzeug bei der Kommunikation mit Menschen rund um den Globus. Unsere Hoffnung ist, dass internationale Studenten Englischkenntnisse erwerben um in der Welt Erfolg zu haben.","Aus diesem Grund fokussieren wir uns auf die Qualität der Kurse und einen niedrigen Preis."]},section3:{image:"\u002Fimages\u002Fwhat-is-mli\u002Fabout\u002Fmli-staff.jpg",title:"Bis zum Jahr 2020 haben über 17,000 Studenten am MLI studiert und abgeschlossen.",description:["Wir bieten ESL Programme (allgemeines Englisch Programm mit 6 Bereichen: Grammatik\u002FSchreiben, Lesen\u002FVokabular und Zuhören\u002FSprechen), TOEFL®, IELTS™ (für Studenten die sich aufs College vorbereiten möchten), und TOEIC®.","Viele Studenten haben danach, innerhalb der USA, zu Universitäten oder ans College gewechselt um zu studieren, zum Beispiel an die UCLA, das USC oder das Santa Monica College."],lists:[{link:"\u002Fde\u002Ffeature",image:a,text:"5 Gründe warum Studenten MLI wählen "},{link:"\u002Fde\u002Fcompany",image:a,text:"Unternehmensinformationen"},{link:"\u002Fde\u002Fimage-gallery",image:a,text:"Foto- \u002F Videogallerie"}]},dir:"\u002Fabout",path:"\u002Fabout\u002Fde",extension:".json",createdAt:"2026-10-22T16:31:28.442Z",updatedAt:"2025-05-26T12:06:27.572Z"}}],fetch:{},mutations:void 0}}("\u002Fimages\u002Ficons\u002Fboxed-arrow.svg","Das Mentor Language Institute  wurde 2002 gegründet und ist an zwei beliebten Standorten vertreten: Westwood & Hollywood.")));